export const progressKey='mecanica.prediction.v1';
export function createProgressStore(storage){let rows=[],warning='';try{const raw=storage.getItem(progressKey);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error();rows=parsed.filter(r=>r&&typeof r.id==='string'&&['pressure','jam','sensor'].includes(r.kind)&&typeof r.signal==='string'&&typeof r.label==='string'&&Number.isFinite(r.errors)&&r.errors>=0&&Number.isFinite(r.hints)&&typeof r.resolved==='boolean'&&Number.isFinite(r.points)&&typeof r.date==='string'&&Array.isArray(r.wrong)).slice(-500);}}catch{warning='No se pudo leer el historial local. Los nuevos resultados se conservan en esta sesión.';}
 return {rows:()=>structuredClone(rows),warning:()=>warning,save(record){const i=rows.findIndex(r=>r.id===record.id);if(i<0)rows.push(structuredClone(record));else rows[i]=structuredClone(record);rows=rows.slice(-500);if(warning)return;try{storage.setItem(progressKey,JSON.stringify(rows));}catch{warning='No se pudo guardar en este navegador. Los resultados nuevos solo durarán esta sesión.';}}};}
export function signalStats(rows){const map=new Map();for(const r of rows){if(!map.has(r.signal))map.set(r.signal,{signal:r.signal,label:r.label,questions:0,errors:0,hints:0,reveals:0,resolved:0,points:0,clean:0});const s=map.get(r.signal);s.questions++;s.errors+=r.errors;s.hints+=r.hints;s.reveals+=Number(r.revealed);if(r.resolved){s.resolved++;s.points+=r.points;if(!r.errors&&!r.hints&&!r.revealed)s.clean++;}}return [...map.values()].map(s=>({...s,mean:s.resolved?Math.round(s.points/s.resolved):null,priority:s.errors+s.hints*.5+s.reveals*2})).sort((a,b)=>b.priority-a.priority||b.questions-a.questions);}
